// === Tab: mySketch ===
let walkers = [];
let numWalkers = 1000; // More walkers for a denser texture
let currentSeed = 53;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(0); // Dark background

  // Initialize walkers
  for (let i = 0; i < numWalkers; i++) {
    walkers.push(new Walker(random(width), random(height)));
  }
}

function draw() {
  // Update and display each walker
  for (let i = 0; i < numWalkers; i++) {
    walkers[i].update();
    walkers[i].show();
  }
}

class Walker {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.stepSize = 1;
  }

  update() {
    // Mouse influence: adjust angle based on mouse proximity
    let angle = noise(this.x*0.01, this.y*0.01,frameCount*0.01) * TWO_PI * 4;
    let distance = dist(this.x, this.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let influenceRadius = 200; // Adjust to control the area of influence

    if (distance < influenceRadius) {
      // Calculate the angle towards the mouse
      let angleToMouse = atan2((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - this.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - this.x);
      angle = lerp(angle, angleToMouse, map(distance, 0, influenceRadius, 1, 0)); // closer to mouse, closer to angleToMouse
    }

    // Random walk with adjusted angle
    this.x += cos(angle) * this.stepSize;
    this.y += sin(angle) * this.stepSize;

    //Boundary conditions, teleporting walkers
    if (this.x < 0) this.x = width;
    if (this.x > width) this.x = 0;
    if (this.y < 0) this.y = height;
    if (this.y > height) this.y = 0;
  }

  show() {
    // Density gradient, darker in the center, brighter in the edges
    let centerDist = dist(this.x, this.y, width / 2, height / 2);
    let maxDist = dist(0, 0, width / 2, height / 2); // Distance from corner to center
    let brightness = map(centerDist, 0, maxDist, 255, 100); // Map distance to brightness, brighter near the edge

    stroke(brightness, 50); // Gray color with transparency for density
    point(this.x, this.y);
  }
}
function keyPressed() {
  if (key === 's') saveCanvas(`artwork_seed_${currentSeed}`, 'png');
}

